import re
import os
import glob
from pathlib import Path

def task_func(pattern, directory, extensions):
    matched_files = []

    # Compile regex pattern with case-insensitive flag
    try:
        regex = re.compile(pattern, re.IGNORECASE)
    except re.error:
        return []

    if not os.path.isdir(directory):
        return []

    # Normalize extensions to ensure they start with a dot
    valid_exts = set(ext if ext.startswith('.') else f'.{ext}' for ext in extensions)

    try:
        # Use os.listdir to avoid issues with glob special characters (like '[' or '*') in the directory path
        for filename in os.listdir(directory):
            file_path = os.path.join(directory, filename)

            if os.path.isfile(file_path):
                _, ext = os.path.splitext(filename)

                # Check if the file's extension is in the provided list
                if ext in valid_exts:
                    try:
                        # Use errors='ignore' to handle potential binary files or invalid utf-8 characters safely
                        with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                            content = f.read()
                            if regex.search(content):
                                matched_files.append(os.path.abspath(file_path))
                    except Exception:
                        continue
    except Exception:
        pass

    return matched_files

